CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,currency char(3) NOT NULL DEFAULT 'UZS',timezone text NOT NULL DEFAULT 'Asia/Tashkent',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,timezone text NOT NULL DEFAULT 'Asia/Tashkent',address text,is_active boolean NOT NULL DEFAULT true,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,UNIQUE(organization_id,name));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),login text NOT NULL,password_hash text NOT NULL,is_active boolean NOT NULL DEFAULT true,must_change_password boolean NOT NULL DEFAULT false,token_version integer NOT NULL DEFAULT 0,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,UNIQUE(organization_id,login));
CREATE TABLE employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL UNIQUE REFERENCES users(id),branch_id uuid REFERENCES branches(id),first_name text NOT NULL,last_name text NOT NULL,position text NOT NULL,specialty text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES organizations(id),code text NOT NULL,name text NOT NULL,is_system boolean NOT NULL DEFAULT false,UNIQUE(organization_id,code));
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,description text NOT NULL);
CREATE TABLE user_roles(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash char(64) NOT NULL UNIQUE,user_agent text,ip_address text,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),branch_id uuid REFERENCES branches(id),actor_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id text,ip_address text,user_agent text,result text NOT NULL,changes jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_branches_org ON branches(organization_id) WHERE deleted_at IS NULL;CREATE INDEX idx_users_org ON users(organization_id) WHERE deleted_at IS NULL;CREATE INDEX idx_sessions_user_active ON sessions(user_id,expires_at) WHERE revoked_at IS NULL;CREATE INDEX idx_audit_org_created ON audit_logs(organization_id,created_at DESC);
INSERT INTO permissions(code,description) VALUES('*','All permissions'),('branches:read','Read branches'),('branches:write','Manage branches'),('employees:read','Read employees'),('employees:write','Manage employees'),('audit:read','Read audit trail') ON CONFLICT DO NOTHING;
